pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256[2] calldata winners, bool callTwice) public {
        // winners: two token IDs to pass to pickWinner
        // callTwice: whether to attempt a second pickWinner call using the same round
        // We need an owner for the fighters, so we deploy a mock FighterFarm that C can call ownerOf on.
        // The reference C interacts with FighterFarm through address, so we provide a simple mock that returns predictable owners.
        MockFighterFarm mockFarm = new MockFighterFarm();
        // Re-deploy C with the mock address as the FighterFarm
        c = new C(address(this), address(this), address(mockFarm));
        // Register winners as tokens owned by address(this)
        mockFarm.setOwner(winners[0], address(this));
        mockFarm.setOwner(winners[1], address(this));
        c.adjustAdminAccess(address(this), true);

        // First pickWinner call
        c.pickWinner(winners);

        // Record roundId after first call
        uint256 roundIdAfterFirst = c.roundId();

        // Second pickWinner call: expects to succeed because roundId should have advanced.
        bool secondPickSucceeded;
        if (callTwice) {
            // We need new winners for the second call; reuse the same ones, but ownerOf must still resolve.
            // Since isSelectionComplete for the old roundId is true in both contracts,
            // the reference will have advanced roundId and succeed; the bug will have unchanged roundId and revert.
            try c.pickWinner(winners) {
                secondPickSucceeded = true;
            } catch {
                secondPickSucceeded = false;
            }
        } else {
            secondPickSucceeded = true; // trivially satisfy assertion when not attempting second call
        }

        // Property: if we called pickWinner once and then attempt a second call,
        // the second call must succeed (reference does because roundId increments) OR we skip the second call.
        // The property tested: after a successful pickWinner, a subsequent pickWinner call must not revert.
        // This holds for the reference because roundId advances, and fails for the bug because roundId stays the same,
        // causing isSelectionComplete check to revert.
        assertTrue(secondPickSucceeded);
    }
}

contract MockFighterFarm {
    mapping(uint256 => address) private _owners;
    function setOwner(uint256 tokenId, address owner) external {
        _owners[tokenId] = owner;
    }
    function ownerOf(uint256 tokenId) external view returns (address) {
        return _owners[tokenId];
    }
}

